<?php
declare(strict_types=1);
namespace TNL\Mail;
require_once __DIR__.'/ExternalMail.php';require_once __DIR__.'/MessageBody.php';require_once __DIR__.'/Directory.php';require_once __DIR__.'/SpamPolicy.php';require_once dirname(__DIR__).'/Admin/Settings.php';
final class Reception {
 public static function init(\PDO $db): void {
  $db->exec("CREATE TABLE IF NOT EXISTS reception_routes(token TEXT PRIMARY KEY,mailbox TEXT NOT NULL,user_id INTEGER NOT NULL,peers TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS reception_links(mailbox TEXT NOT NULL,message_id TEXT NOT NULL,token TEXT NOT NULL,PRIMARY KEY(mailbox,message_id)); CREATE TABLE IF NOT EXISTS reception_messages(id INTEGER PRIMARY KEY,mailbox TEXT NOT NULL,validity INTEGER NOT NULL,uid INTEGER NOT NULL,message_id TEXT NOT NULL,token TEXT NOT NULL,sender TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,html TEXT NOT NULL,images TEXT NOT NULL,headers TEXT NOT NULL,assigned_user INTEGER NOT NULL DEFAULT 0,read_at TEXT,created_at TEXT NOT NULL,UNIQUE(mailbox,validity,uid)); CREATE UNIQUE INDEX IF NOT EXISTS reception_message_identity ON reception_messages(mailbox,message_id) WHERE message_id<>''; CREATE TABLE IF NOT EXISTS reception_contacts(mailbox TEXT NOT NULL,sender TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(mailbox,sender)); CREATE TABLE IF NOT EXISTS reception_sync(mailbox TEXT PRIMARY KEY,validity INTEGER NOT NULL,next_uid INTEGER NOT NULL,last_poll INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT ''); CREATE TABLE IF NOT EXISTS reception_errors(mailbox TEXT NOT NULL,validity INTEGER NOT NULL,uid INTEGER NOT NULL,error TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(mailbox,validity,uid))");
 }
 public static function owner(\PDO $db): string {return \TNL\Admin\Settings::get($db,'reception_enabled')==='1'?\TNL\Admin\Settings::get($db,'reception_owner'):'';}
 public static function signingKey(string $storage): string {
  $file=$storage.'/reception-routing.key';if(is_link($file))throw new \RuntimeException('Clave de recepción inválida.');$lock=fopen($storage.'/reception-key.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new \RuntimeException('No se pudo bloquear la clave.');try{if(!is_file($file)){$f=fopen($file,'xb');if(!$f)throw new \RuntimeException('No se pudo crear clave.');chmod($file,0600);fwrite($f,random_bytes(32));fclose($f);}$key=file_get_contents($file);if(strlen($key)!==32)throw new \RuntimeException('Clave de recepción inválida.');return $key;}finally{flock($lock,LOCK_UN);fclose($lock);}
 }
 public static function token(\PDO $db,string $owner,int $user,array $peers): string {self::init($db);$token=bin2hex(random_bytes(16));$db->prepare('INSERT INTO reception_routes VALUES(?,?,?,?,?)')->execute([$token,$owner,$user,json_encode(array_values(array_unique(array_map('strtolower',$peers)))),gmdate('c')]);return $token;}
 public static function marker(string $token,string $storage): string {return $token.'.'.hash_hmac('sha256',$token,self::signingKey($storage));}
 public static function verify(string $value,string $storage): string {if(!preg_match('/^([a-f0-9]{32})\.([a-f0-9]{64})$/D',$value,$m))return '';return hash_equals(hash_hmac('sha256',$m[1],self::signingKey($storage)),$m[2])?$m[1]:'';}
 public static function link(\PDO $db,string $owner,string $id,string $token): void {if(ReplyComposer::messageId($id)!=='')$db->prepare('INSERT OR IGNORE INTO reception_links VALUES(?,?,?)')->execute([$owner,$id,$token]);}
 public static function staff(\PDO $db): array {\TNL\Admin\Users::init($db);return $db->query('SELECT id,username,internal_address,display_name,job_title,department FROM users WHERE active=1 ORDER BY display_name')->fetchAll(\PDO::FETCH_ASSOC);}
 private static function normalized(string $s): string {$s=strtolower(trim($s));if(function_exists('iconv')){$x=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s);if($x!==false)$s=strtolower($x);}return trim(preg_replace('/[^a-z0-9@.]+/',' ',$s));}
 public static function resolveChoice(\PDO $db,string $body): int {$line='';foreach(preg_split('/\r?\n/',$body) as $part){$part=trim($part);if($part!==''&&!str_starts_with($part,'>')){$line=substr($part,0,300);break;}}$needle=self::normalized($line);if($needle==='')return 0;$matches=[];foreach(self::staff($db) as $u){$variants=[$u['username'],$u['internal_address'],$u['display_name'],$u['display_name'].' '.$u['job_title'],$u['username'].' '.$u['job_title'],$u['department']];foreach($variants as $v)if($v!==''&&self::normalized($v)===$needle)$matches[(int)$u['id']]=true;}return count($matches)===1?(int)array_key_first($matches):0;}
 public static function outbound(\PDO $db,string $owner,int $user,array $peers,string $storage): array {if($owner!==self::owner($db)||$user<1)return [];self::init($db);$q=$db->prepare('SELECT internal_address,job_title FROM users WHERE id=? AND active=1');$q->execute([$user]);$u=$q->fetch(\PDO::FETCH_ASSOC);if(!$u)throw new \InvalidArgumentException('Usuario interno no disponible.');$token=self::token($db,$owner,$user,$peers);return ['token'=>$token,'route_marker'=>self::marker($token,$storage),'route_identity'=>$u['internal_address'].($u['job_title']?' ('.$u['job_title'].')':'')];}
 public static function activate(\PDO $db,string $owner,string $storage): array {self::init($db);$store=new ExternalAccount($db,$storage);$account=$store->load($owner);if(!$account)throw new \InvalidArgumentException('Buzón no configurado.');$imap=new ImapClient($account);try{$imap->connect();$state=$imap->checkpoint();}finally{$imap->close();}if($state['validity']<1)throw new \RuntimeException('UIDVALIDITY no disponible.');$db->prepare("INSERT INTO reception_sync(mailbox,validity,next_uid,last_poll) VALUES(?,?,?,?) ON CONFLICT(mailbox) DO UPDATE SET validity=excluded.validity,next_uid=excluded.next_uid,last_poll=excluded.last_poll,last_error=''")->execute([$owner,$state['validity'],$state['next'],time()]);\TNL\Admin\Settings::set($db,'reception_owner',$owner);\TNL\Admin\Settings::set($db,'reception_enabled','1');return ['email'=>$account['email'],'start_uid'=>$state['next'],'old_mail_skipped'=>true];}
 private static function route(\PDO $db,string $owner,string $token,string $sender): ?array {$q=$db->prepare('SELECT * FROM reception_routes WHERE token=? AND mailbox=?');$q->execute([$token,$owner]);$r=$q->fetch(\PDO::FETCH_ASSOC);return $r&&in_array(strtolower($sender),json_decode($r['peers'],true),true)?$r:null;}
 public static function ingest(\PDO $db,string $owner,int $validity,int $uid,array $message,string $storage): array {self::init($db);$own=!$db->inTransaction();if($own)$db->beginTransaction();try{$result=self::ingestMessage($db,$owner,$validity,$uid,$message,$storage);if($own)$db->commit();return $result;}catch(\Throwable $e){if($own&&$db->inTransaction())$db->rollBack();throw $e;}}
 private static function ingestMessage(\PDO $db,string $owner,int $validity,int $uid,array $message,string $storage): array {
  self::init($db);$h=$message['headers'];$mid=ReplyComposer::messageId($h['message-id']??'');$q=$db->prepare("SELECT id FROM reception_messages WHERE mailbox=? AND ((validity=? AND uid=?) OR (message_id<>'' AND message_id=?))");$q->execute([$owner,$validity,$uid,$mid]);if($q->fetchColumn())return ['duplicate'=>true,'auto_reply'=>false];$sender=ReplyComposer::address($h['from']??'');if($sender==='')throw new \InvalidArgumentException('Remitente ambiguo.');$route=null;$direct=[];
  foreach(['x-original-to','delivered-to','envelope-to','to'] as $field)foreach(preg_split('/[,;]/',$h[$field]??'') as $v){$email=ReplyComposer::address($v);if($email==='')continue;foreach(self::staff($db) as $u)if(strcasecmp($email,$u['internal_address'])===0)$direct[(int)$u['id']]=true;}
  if(count($direct)===1){$token=self::token($db,$owner,(int)array_key_first($direct),[$sender]);$route=self::route($db,$owner,$token,$sender);}
  if(!$direct){preg_match_all('/<[^<>\s]+@[^<>\s]+>/',($h['in-reply-to']??'').' '.($h['references']??''),$ids);foreach(array_reverse($ids[0]) as $ref){$q=$db->prepare('SELECT token FROM reception_links WHERE mailbox=? AND message_id=?');$q->execute([$owner,$ref]);$t=$q->fetchColumn();if($t&&($r=self::route($db,$owner,$t,$sender))){$route=$r;break;}}
   if(!$route&&preg_match('/(?:tnl-route[=: ]|^)([a-f0-9]{32}\.[a-f0-9]{64})/',($h['x-tnl-route']??'').' '.($message['html']??''),$mark)){$t=self::verify($mark[1],$storage);if($t!=='')$route=self::route($db,$owner,$t,$sender);}
  }
  if(!$route){$token=self::token($db,$owner,0,[$sender]);$route=self::route($db,$owner,$token,$sender);}$user=(int)$route['user_id'];if($user===0&&($choice=self::resolveChoice($db,isset($message['plain'])&&!$message['plain']&&!empty($message['html'])?MessageBody::plain($message['html'],'html'):($message['body']??'')))>0){$user=$choice;$db->prepare('UPDATE reception_routes SET user_id=? WHERE token=?')->execute([$user,$route['token']]);$db->prepare('UPDATE reception_messages SET assigned_user=? WHERE token=? AND mailbox=?')->execute([$user,$route['token'],$owner]);}
  if($user>0){$q=$db->prepare('SELECT id FROM users WHERE id=? AND active=1');$q->execute([$user]);if(!$q->fetchColumn())$user=0;}
  $db->prepare('INSERT INTO reception_messages(mailbox,validity,uid,message_id,token,sender,subject,body,html,images,headers,assigned_user,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$owner,$validity,$uid,$mid,$route['token'],$sender,substr($h['subject']??'(sin asunto)',0,500),$message['body']??'',$message['html']??'',json_encode($message['inline_images']??[]),json_encode($h),$user,gmdate('c')]);self::link($db,$owner,$mid,$route['token']);
  $automatic=(!$user)&&!(new SpamPolicy($db))->blocked($owner,$sender)&&!preg_match('/^(?:yes|spam)/i',$h['x-spam-status']??$h['x-spam-flag']??'')&&!isset($h['list-id'])&&(!isset($h['auto-submitted'])||strtolower($h['auto-submitted'])==='no')&&!preg_match('/(?:bulk|list|junk)/i',$h['precedence']??'')&&!preg_match('/(?:mailer-daemon|postmaster|no-?reply)/i',$sender)&&($h['return-path']??'')!=='<>';
  return ['duplicate'=>false,'user_id'=>$user,'token'=>$route['token'],'auto_reply'=>$automatic,'sender'=>$sender,'headers'=>$h];
 }
 public static function read(\PDO $db,int $id,int $user,bool $admin=false): ?array {self::init($db);$q=$db->prepare('SELECT * FROM reception_messages WHERE id=?'.($admin?'':' AND assigned_user=?'));$q->execute($admin?[$id]:[$id,$user]);$m=$q->fetch(\PDO::FETCH_ASSOC);if($m&&!$admin)$db->prepare('UPDATE reception_messages SET read_at=? WHERE id=? AND assigned_user=?')->execute([gmdate('c'),$id,$user]);return $m?:null;}
 public static function assign(\PDO $db,int $id,int $user): void {self::init($db);$q=$db->prepare('SELECT token FROM reception_messages WHERE id=?');$q->execute([$id]);$token=$q->fetchColumn();$q=$db->prepare('SELECT id FROM users WHERE id=? AND active=1');$q->execute([$user]);if(!$token||!$q->fetchColumn())throw new \InvalidArgumentException('Asignación inválida.');$db->prepare('UPDATE reception_routes SET user_id=? WHERE token=?')->execute([$user,$token]);$db->prepare('UPDATE reception_messages SET assigned_user=? WHERE token=?')->execute([$user,$token]);}
}
